mapper.select:
select *
  from batch.batch_day_instance
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date = #{bizDate}

select max(biz_date)
  from batch.batch_day_instance
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date <= #{bizDate}

select biz_date
  from batch.batch_day_instance
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date between #{fromDate} and #{throughDate}
 order by biz_date

select last_scanned_biz_date
  from batch.batch_day_open_cursor
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
 for update

select last_scanned_biz_date
  from batch.batch_day_open_cursor
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}

mapper.update:
update batch.batch_day_open_cursor
   set last_scanned_biz_date = #{nextBizDate},
       last_scan_at = #{scannedAt},
       updated_at = current_timestamp
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and last_scanned_biz_date = #{expectedBizDate}

